/* Word finder and Word Bomb style practice on the ENABLE list. The build prepends WF_DATA (practice
 * combos by difficulty and the URL of the front coded word file: each line is one character,
 * '0' plus how many letters it shares with the previous word, then the rest of the word). */
(function () {
  "use strict";
  var root = document.getElementById("word-tool");
  if (!root || !window.WF_DATA) return;
  var DATA = window.WF_DATA;
  var SHOW = 240;
  var words = null, loading = null;

  var form = root.querySelector(".wf-search");
  var input = form.querySelector("[name=letters]");
  var mode = form.querySelector("[name=mode]");
  var out = root.querySelector(".wf-out");

  function load() {
    if (words) return Promise.resolve(words);
    if (!loading) {
      out.innerHTML = "<p>Loading the word list…</p>";
      loading = fetch(DATA.words).then(function (r) {
        if (!r.ok) throw new Error(r.status);
        return r.text();
      }).then(function (text) {
        var list = [], prev = "";
        text.split("\n").forEach(function (line) {
          if (!line) return;
          prev = prev.slice(0, line.charCodeAt(0) - 48) + line.slice(1);
          list.push(prev);
        });
        words = list;
        return words;
      });
    }
    return loading;
  }

  function clean(s) { return String(s || "").toLowerCase().replace(/[^a-z]/g, "").slice(0, 12); }

  function search(showAll) {
    var q = clean(input.value);
    if (!q) {
      out.innerHTML = "<p>Type a few letters, like ing or qu.</p>";
      return;
    }
    load().then(function (list) {
      var how = mode.value;
      var hits = list.filter(function (w) {
        return how === "starts" ? w.indexOf(q) === 0 : how === "ends" ? w.slice(-q.length) === q : w.indexOf(q) >= 0;
      });
      hits.sort(function (a, b) { return a.length - b.length || (a < b ? -1 : 1); });
      var label = { contains: "containing", starts: "starting with", ends: "ending with" }[how];
      var html = "<p><strong>" + hits.length.toLocaleString("en") + "</strong> words " + label + " " + q.toUpperCase() +
        (hits.length > SHOW && !showAll ? ". Here are the " + SHOW + " shortest." : ".") + "</p>";
      if (!hits.length) html += "<p>No words in the list. Try fewer letters, or check the spelling.</p>";
      var shown = showAll ? hits : hits.slice(0, SHOW);
      var byLen = {};
      shown.forEach(function (w) { (byLen[w.length] = byLen[w.length] || []).push(w); });
      Object.keys(byLen).forEach(function (len) {
        html += '<h3 class="wf-len">' + len + " letters</h3><p class=\"wf-words\">" + byLen[len].map(function (w) {
          var i = how === "ends" ? w.length - q.length : w.indexOf(q);
          return "<span>" + w.slice(0, i) + "<b>" + w.slice(i, i + q.length) + "</b>" + w.slice(i + q.length) + "</span>";
        }).join(" ") + "</p>";
      });
      if (hits.length > SHOW && !showAll) html += '<p><button type="button" class="btn-ghost" data-all>Show all ' + hits.length.toLocaleString("en") + " words</button></p>";
      out.innerHTML = html;
    }).catch(function () {
      out.innerHTML = "<p>The word list didn't load. Check your connection and try again.</p>";
      loading = null;
    });
  }

  form.addEventListener("submit", function (e) {
    e.preventDefault();
    search(false);
  });
  mode.addEventListener("change", function () { if (input.value) search(false); });
  out.addEventListener("click", function (e) {
    if (e.target.closest("[data-all]")) search(true);
  });

  /* ---------- Practice: one hidden fuse, as many words as you can ---------- */

  var game = root.querySelector(".wf-game");
  var prompt = game.querySelector(".wf-prompt");
  var answer = game.querySelector("[name=answer]");
  var note = game.querySelector(".wf-note");
  var startBtn = game.querySelector("[data-start]");
  var level = game.querySelector("[name=level]");
  var used = {}, found = [], combo = "", fuse = 0, playing = false, fuseLeft = 0;

  function pick() {
    var list = DATA.tiers[level.value];
    var next = combo;
    while (next === combo) next = list[Math.floor(Math.random() * list.length)];
    combo = next;
    prompt.textContent = combo.toUpperCase();
  }

  function boom() {
    playing = false;
    answer.disabled = true;
    startBtn.disabled = false;
    startBtn.textContent = "Play again";
    game.classList.remove("is-lit");
    game.classList.add("is-boom");
    var examples = words.filter(function (w) { return w.indexOf(combo) >= 0 && w.length <= 7; })
      .sort(function (a, b) { return a.length - b.length; }).slice(0, 5);
    note.innerHTML = "<strong>Boom.</strong> You found " + found.length + (found.length === 1 ? " word" : " words") +
      (found.length ? ": " + found.join(", ") + "." : ".") + " For " + combo.toUpperCase() + " you could have said " + examples.join(", ") + ".";
  }

  function start() {
    load().then(function () {
      used = {};
      found = [];
      playing = true;
      game.classList.remove("is-boom");
      game.classList.add("is-lit");
      answer.disabled = false;
      answer.value = "";
      answer.focus();
      startBtn.disabled = true;
      note.textContent = "The fuse is lit. Type a word with these letters and press Enter.";
      pick();
      fuseLeft = 30000 + Math.floor(Math.random() * 30001);
      clearTimeout(fuse);
      fuse = setTimeout(boom, fuseLeft);
    });
  }

  game.querySelector("form").addEventListener("submit", function (e) {
    e.preventDefault();
    if (!playing) return;
    var w = clean(answer.value);
    answer.value = "";
    if (!w) return;
    if (w.indexOf(combo) < 0) note.textContent = w.toUpperCase() + " doesn't contain " + combo.toUpperCase() + ".";
    else if (used[w]) note.textContent = "You already used " + w.toUpperCase() + ".";
    else if (!binaryHas(w)) note.textContent = w.toUpperCase() + " isn't in the word list.";
    else {
      used[w] = 1;
      found.push(w);
      note.textContent = "Yes, " + w.toUpperCase() + ". " + found.length + (found.length === 1 ? " word" : " words") + " so far.";
      pick();
    }
  });

  function binaryHas(w) {
    var lo = 0, hi = words.length - 1;
    while (lo <= hi) {
      var mid = (lo + hi) >> 1;
      if (words[mid] === w) return true;
      if (words[mid] < w) lo = mid + 1;
      else hi = mid - 1;
    }
    return false;
  }

  startBtn.addEventListener("click", start);
  document.addEventListener("visibilitychange", function () {
    if (document.hidden && playing) {
      clearTimeout(fuse);
      playing = false;
      answer.disabled = true;
      startBtn.disabled = false;
      startBtn.textContent = "Start again";
      game.classList.remove("is-lit");
      note.textContent = "Paused because you left the page. The bomb is defused, for now.";
    }
  });
  root.setAttribute("data-ready", "1");
})();
